* {
  box-sizing: border-box;
}
body {
  margin: 0;
  font-family: -apple-system, 'PingFang SC', 'Microsoft YaHei', 'Segoe UI', sans-serif;
  background: #f2f4f8;
  color: #1f2937;
  font-size: 14px;
}
.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 0 24px;
  height: 56px;
  background: #1e3a5f;
  color: #fff;
}
.brand {
  font-weight: 700;
  font-size: 16px;
}
.topbar nav {
  display: flex;
  gap: 8px;
}
.navbtn,
.tabs .tab {
  background: transparent;
  border: none;
  color: #c8d6e8;
